// Independent isolated examination receiver; no external channel or real person.
import fs from 'node:fs';import readline from 'node:readline';import {createHash} from 'node:crypto';
const file=process.argv[2],seen=new Map();const hash=x=>createHash('sha256').update(x).digest('hex');
for await(const line of readline.createInterface({input:process.stdin})){const input=JSON.parse(line);if(input.mode==='HANG')continue;const digest=hash(input.body);if(input.mode==='REJECT'){process.stdout.write(JSON.stringify({requestId:input.requestId,digest,success:false})+'\n');continue;}const previous=seen.get(input.incidentId);if(previous&&previous!==digest){process.stdout.write(JSON.stringify({requestId:input.requestId,digest,success:false})+'\n');continue;}if(!previous){const fd=fs.openSync(file,'a',0o600);try{fs.writeSync(fd,JSON.stringify({incidentId:input.incidentId,body:input.body,digest,receivedAt:Date.now(),classification:'ISOLATED_RECEIVER_NOT_REAL_OWNER'})+'\n');fs.fsyncSync(fd);}finally{fs.closeSync(fd);}seen.set(input.incidentId,digest);}process.stdout.write(JSON.stringify({requestId:input.requestId,digest,success:true})+'\n');}
